import java.nio.file.*;import java.util.*;import java.security.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class MeteorRegistrationPatch {
 static String hash(MethodNode m)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(OpeningDelta.norm(m).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 static MethodNode get(ClassNode c){return c.methods.stream().filter(m->m.name.equals("mechanic")&&m.desc.equals("(Lio/lumine/mythic/bukkit/events/MythicMechanicLoadEvent;)V")).findFirst().orElseThrow();}
 public static void main(String[]a)throws Exception{
 byte[] bytes=Files.readAllBytes(Path.of(a[0]));var reader=new ClassReader(bytes);var live=new ClassNode();reader.accept(live,0);var expanded=new ClassNode();reader.accept(expanded,ClassReader.EXPAND_FRAMES);var raw=OpeningDelta.read(Files.readAllBytes(Path.of(a[1])),0);var old=get(live);var target=get(expanded);String original=OpeningDelta.norm(old);
 if(target.instructions.iterator().hasNext()==false)throw new IllegalStateException("empty");
 for(var n:target.instructions)if(n instanceof TypeInsnNode t&&t.desc.endsWith("/MeteorMech"))throw new IllegalStateException("meteor already registered");
 MethodInsnNode register=null,meteorCtor=null;for(var n:get(raw).instructions)if(n instanceof MethodInsnNode m){if(m.name.equals("register")&&m.owner.endsWith("/MythicMechanicLoadEvent"))register=m;if(m.name.equals("<init>")&&m.owner.endsWith("/MeteorMech"))meteorCtor=m;}if(register==null||meteorCtor==null)throw new IllegalStateException("source case not found");
 boolean params=false,constructed=false;VarInsnNode anchor=null;for(var n:target.instructions){if(n instanceof TypeInsnNode t&&t.desc.equals("school/chacademia/magicmythic/Params"))params=true;if(params&&n instanceof MethodInsnNode m&&m.name.equals("<init>")&&m.owner.equals("school/chacademia/magicmythic/Params"))constructed=true;if(constructed&&n instanceof VarInsnNode v&&v.getOpcode()==Opcodes.ASTORE){anchor=v;break;}}
 if(anchor==null||anchor.var!=3)throw new IllegalStateException("unexpected Params local");var add=new InsnList();var skip=new LabelNode();
 add.add(new VarInsnNode(Opcodes.ALOAD,2));add.add(new LdcInsnNode("chameteor"));add.add(new MethodInsnNode(Opcodes.INVOKEVIRTUAL,"java/lang/String","equals","(Ljava/lang/Object;)Z",false));add.add(new JumpInsnNode(Opcodes.IFEQ,skip));
 add.add(new VarInsnNode(Opcodes.ALOAD,1));add.add(new TypeInsnNode(Opcodes.NEW,meteorCtor.owner));add.add(new InsnNode(Opcodes.DUP));add.add(new VarInsnNode(Opcodes.ALOAD,0));add.add(new VarInsnNode(Opcodes.ALOAD,3));add.add(new MethodInsnNode(meteorCtor.getOpcode(),meteorCtor.owner,meteorCtor.name,meteorCtor.desc,meteorCtor.itf));add.add(new MethodInsnNode(register.getOpcode(),register.owner,register.name,register.desc,register.itf));add.add(new InsnNode(Opcodes.RETURN));add.add(skip);add.add(new FrameNode(Opcodes.F_NEW,4,new Object[]{live.name,"io/lumine/mythic/bukkit/events/MythicMechanicLoadEvent","java/lang/String","school/chacademia/magicmythic/Params"},0,null));
 var inserted=new ArrayList<AbstractInsnNode>();for(var n:add)inserted.add(n);target.instructions.insert(anchor,add);
 var patched=new MethodNode(target.access,target.name,target.desc,target.signature,target.exceptions.toArray(String[]::new));target.accept(patched);for(var n:inserted)target.instructions.remove(n);if(!OpeningDelta.norm(target).equals(original))throw new IllegalStateException("strip differs from live registration");live.methods.remove(old);live.methods.add(patched);var writer=new ClassWriter(reader,ClassWriter.COMPUTE_MAXS);live.accept(writer);byte[] result=writer.toByteArray();var check=OpeningDelta.read(result,0);var before=OpeningDelta.read(bytes,0);int unchanged=0;
 for(var m:before.methods)if(!m.name.equals("mechanic")){var after=check.methods.stream().filter(x->OpeningDelta.key(x).equals(OpeningDelta.key(m))).findFirst().orElseThrow();if(!hash(m).equals(hash(after)))throw new IllegalStateException("other method changed "+OpeningDelta.key(m));unchanged++;System.out.println("METHOD_HASH_UNCHANGED "+OpeningDelta.key(m)+" "+hash(m));}
 int count=0;var names=new TreeSet<String>();var types=new TreeSet<String>();for(var n:get(check).instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==Opcodes.NEW){types.add(t.desc);if(t.desc.endsWith("/MeteorMech"))count++;}if(n instanceof LdcInsnNode l&&l.cst instanceof String s&&s.matches("cha[a-z]+"))names.add(s);}if(count!=1)throw new IllegalStateException("meteor construction count "+count);
 for(var m:check.methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(check.name,m);
 Files.write(Path.of(a[2]),result);System.out.println("REGISTERED_NAMES "+String.join(",",names));System.out.println("REGISTERED_TYPES "+String.join(",",types));System.out.println("PASS METEOR_REGISTRATION sourceCtorAndRegister=true targetOnlyBranch=chameteor newInstances=1 stripEqualsOperatingMethod=true otherMethodsHashIdentical="+unchanged+" fieldsUnchanged="+before.fields.size());
 }
}
